    const minRUN = 32;

// Calculate minimum run length (kept small here for demo)
function calcMinRun(n) {
    let r = 0;
    while (n >= minRUN) {
        r |= n & 1;
        n >>= 1;
    }
    return n + r;
}

// Insertion sort for small ranges
